  show("Eager","pl.DataFrame - executes immediately");
  show("Lazy","pl.LazyFrame - builds a plan, runs on .collect()");
  show("Rule","lazy for pipelines, eager for exploration");
}else if(m==="scan"){
  show("scan_csv / scan_parquet","lazy readers");
  show("Predicate pushdown","filters apply during the read");
